@once
<style>
.warehouse-report{--navy:#07143e;--green:#08b63f;--line:#dfe6ef;--muted:#66728f;color:var(--navy);font-family:Inter,system-ui,sans-serif;max-width:1900px;margin:auto}.warehouse-report svg{fill:none;stroke:currentColor;stroke-width:1.9;stroke-linecap:round;stroke-linejoin:round}.wr-symbols{position:absolute;width:0;height:0;overflow:hidden}.wr-header,.wr-heading,.wr-actions,.wr-card-head{display:flex;align-items:center}.wr-header{justify-content:space-between;gap:20px;margin-bottom:16px}.wr-heading{gap:16px}.wr-logo{width:58px;height:58px;display:grid;place-items:center;background:linear-gradient(145deg,#3bd65e,#04a936);color:#fff;border-radius:14px;box-shadow:0 8px 20px #0ab54333}.wr-logo svg{width:32px;height:32px}.wr-heading h1{font-size:28px;margin:0;font-weight:800;letter-spacing:-.8px}.wr-heading p{margin:3px 0 0;color:var(--muted);font-size:13px}.wr-actions{gap:10px}.wr-period,.wr-button{min-height:42px;border:1px solid var(--line);background:#fff;border-radius:10px;padding:0 14px;color:var(--navy);font-weight:700;box-shadow:0 3px 9px #132b5210}.wr-period{display:flex;align-items:center;gap:8px}.wr-button{cursor:pointer}.wr-filter{background:#fff;border:1px solid var(--line);border-radius:14px;padding:14px;margin-bottom:16px}.wr-filter .form-label{font-size:11px}.wr-filter .form-control,.wr-filter .form-select{min-height:38px}
.wr-hero{position:relative;display:grid;grid-template-columns:280px 1fr 190px;align-items:center;min-height:142px;padding:20px 22px;background:linear-gradient(100deg,#ecfbf2,#f4fff8 58%,#c8f6dd);border:1px solid #d4f2df;border-radius:16px;overflow:hidden}.wr-hero-title h2{font-size:25px;margin:0;font-weight:800}.wr-hero-title p{margin:6px 0;color:#435477;font-size:12px}.wr-hero-kpis{display:grid;grid-template-columns:repeat(6,minmax(100px,1fr));z-index:2}.wr-hero-kpis article{min-width:0;padding:2px 13px;border-left:1px solid #badccb}.wr-hero-kpis svg{width:20px;height:20px;color:var(--green);float:left;margin-right:6px}.wr-hero-kpis span{font-size:10px;font-weight:700;white-space:nowrap}.wr-hero-kpis strong{display:block;clear:both;font-size:20px;line-height:1.35;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.wr-hero-kpis small{display:inline-block;background:#d5f8d0;color:#087b29;border-radius:12px;padding:2px 7px;font-weight:700;font-size:8px}.wr-warehouse-art{height:100px;position:relative;background:linear-gradient(155deg,transparent 29%,#0ca950 30% 43%,transparent 44%)}.wr-warehouse-art i{position:absolute;inset:38px 20px 5px;background:#f6fbff;border:3px solid #b7d7e2;box-shadow:inset 0 -18px #d8eef5}.wr-warehouse-art b{position:absolute;top:44px;left:65px;font-size:9px;background:#0aa85a;color:#fff;padding:2px 7px}.wr-warehouse-art span{position:absolute;right:20px;bottom:-2px;font-size:40px;color:#ee9e18}
.wr-mini-grid{display:grid;grid-template-columns:repeat(5,1fr);gap:12px;margin:14px 0}.wr-mini,.wr-card{background:#fff;border:1px solid var(--line);border-radius:14px;box-shadow:0 4px 13px #1b31520d}.wr-mini{display:flex;align-items:center;gap:10px;padding:15px;min-width:0}.wr-mini>svg{width:26px;height:26px;color:var(--green);flex:none}.wr-mini div{min-width:0}.wr-mini span,.wr-mini small{display:block;font-size:10px;font-weight:700}.wr-mini small{color:var(--muted);font-weight:500}.wr-mini strong{display:block;font-size:18px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.wr-mini.blue{background:linear-gradient(135deg,#096292,#03426e);color:#fff}.wr-mini.blue svg,.wr-mini.blue small{color:#fff}.wr-mini.orange svg{color:#f59e0b}.wr-mini.cyan svg{color:#1684c8}
.wr-chart-grid{display:grid;grid-template-columns:1.45fr .85fr 1fr;gap:12px;margin-bottom:12px}.wr-card{padding:15px;min-width:0}.wr-card-head{justify-content:space-between;gap:8px;margin-bottom:11px}.wr-card-head h2{font-size:15px;margin:0;font-weight:800;display:flex;align-items:center;gap:7px}.wr-card-head h2 svg{width:21px;height:21px;color:var(--green)}.wr-card-head a{font-size:10px;color:#079236;font-weight:800;background:#eafbed;border-radius:14px;padding:4px 9px;white-space:nowrap}.wr-pill{font-size:10px;background:#e5efff;color:#1863c8;padding:4px 8px;border-radius:8px}.wr-line-chart{width:100%;height:170px}.wr-line-chart .grid{stroke:#edf1f6;stroke-width:1}.wr-line-chart .line{fill:none;stroke-width:3}.wr-line-chart .incoming{stroke:#08b53f}.wr-line-chart .outgoing{stroke:#2675e8}.wr-line-chart .point{fill:#fff;stroke-width:3;cursor:pointer;transition:.15s}.wr-line-chart .point:hover{r:8;filter:drop-shadow(0 2px 3px #0b173744)}.wr-legend{display:flex;justify-content:center;gap:17px;font-size:10px}.wr-legend i,.wr-status-list i{display:inline-block;width:9px;height:9px;border-radius:50%;margin-right:5px}.wr-legend .in,.wr-status-list .green{background:#08b53f}.wr-legend .out{background:#2675e8}.wr-donut-row{display:flex;align-items:center;gap:16px;min-height:170px}.wr-donut{width:115px;height:115px;flex:none;border-radius:50%;display:grid;place-content:center;text-align:center;background:radial-gradient(circle,#fff 52%,transparent 54%),conic-gradient(#08b53f 0 var(--normal),#f6a313 var(--normal) var(--critical),#ef3e59 var(--critical) 100%);transition:.2s}.wr-donut:hover{transform:scale(1.04);filter:drop-shadow(0 5px 8px #17294c22)}.wr-donut b{font-size:24px}.wr-donut span{font-size:10px}.wr-status-list{flex:1}.wr-status-list div{display:flex;justify-content:space-between;gap:6px;font-size:9px;padding:8px 0;border-bottom:1px solid #edf1f5;cursor:help}.wr-status-list .orange{background:#f6a313}.wr-status-list .red{background:#ef3e59}.wr-bars-chart{display:flex;align-items:end;gap:9px;height:175px;border-bottom:1px solid #dfe6ef;padding:10px}.wr-bar-column{flex:1;height:100%;display:flex;flex-direction:column;justify-content:end;align-items:center;gap:5px}.wr-bars{height:135px;width:100%;display:flex;align-items:end;justify-content:center;gap:2px}.wr-bars i{width:38%;min-height:3px;transition:.2s;cursor:pointer}.wr-bars i:hover{filter:brightness(.75);transform:scaleX(1.15)}.wr-bars .in{background:#08b53f}.wr-bars .out{background:#2675e8}.wr-bar-column span{font-size:8px;white-space:nowrap}
.wr-detail-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.wr-stats{display:grid;grid-template-columns:repeat(2,1fr);border-bottom:1px solid #e7ebf1;margin-bottom:8px}.wr-stats.three{grid-template-columns:repeat(3,1fr)}.wr-stats div{padding:5px 10px 10px;border-right:1px solid #e7ebf1;min-width:0}.wr-stats div:last-child{border:0}.wr-stats span{display:block;font-size:9px;color:var(--muted);font-weight:700}.wr-stats b{display:block;font-size:16px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.wr-table-wrap{overflow-x:auto}.wr-table-wrap table{width:100%;border-collapse:collapse;font-size:9px}.wr-table-wrap th{background:#f1f4f8;color:#52607d;text-align:left;padding:6px;white-space:nowrap}.wr-table-wrap td{padding:6px;border-bottom:1px solid #edf0f4;white-space:nowrap}.wr-table-wrap td:nth-child(2){white-space:normal;min-width:90px}.wr-status{display:inline-block;background:#ddf8e3;color:#087c2c;padding:2px 6px;border-radius:10px}.wr-mini-bars>div{display:grid;grid-template-columns:42px 1fr;align-items:center;gap:7px;margin:8px 0;font-size:9px}.wr-mini-bars i{height:13px;background:#edf1f5;border-radius:5px;display:flex;overflow:hidden}.wr-mini-bars b{height:100%;cursor:pointer}.wr-mini-bars .in{background:#08b53f}.wr-mini-bars .out{background:#2675e8}.wr-suppliers>div{display:grid;grid-template-columns:minmax(90px,1fr) 1.3fr auto;align-items:center;gap:8px;font-size:9px;margin:10px 0}.wr-suppliers span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.wr-suppliers i{height:8px;background:#e9edf3;border-radius:5px;overflow:hidden}.wr-suppliers i b{display:block;height:100%;background:linear-gradient(90deg,#08b53f,#48d86b)}.wr-health{display:flex;gap:10px;align-items:center;background:#effaf2;border:1px solid #d3f0dc;border-radius:10px;padding:14px;margin-top:14px}.wr-health>span,.wr-insight li span{display:grid;place-items:center;border-radius:50%;background:#08a83b;color:#fff}.wr-health>span{width:24px;height:24px}.wr-health b{font-size:11px}.wr-health p{font-size:9px;color:var(--muted);margin:2px 0}.wr-insight{position:relative;background:linear-gradient(135deg,#fff,#effbf2);overflow:hidden}.wr-insight ul{list-style:none;padding:0;margin:0;position:relative;z-index:2}.wr-insight li{display:flex;align-items:center;gap:7px;background:#ecf9f0;border:1px solid #d2ecda;border-radius:12px;padding:6px 9px;margin:6px 0;font-size:9px}.wr-insight li span{width:15px;height:15px;font-size:9px}.wr-insight-art{position:absolute;right:18px;bottom:16px;width:66px;height:75px;background:#0a9e3c;color:#fff;border-radius:8px 8px 14px 14px;display:grid;place-items:center;font-size:35px;transform:rotate(5deg);opacity:.9}.wr-insight-art small{position:absolute;right:38px;bottom:-10px;color:#d88916;font-size:30px;white-space:nowrap}.wr-empty{display:grid!important;place-items:center;color:var(--muted);font-size:10px;min-height:80px;width:100%!important}
@media(max-width:1400px){.wr-hero{grid-template-columns:230px 1fr}.wr-warehouse-art{display:none}.wr-hero-kpis{grid-template-columns:repeat(3,1fr);row-gap:12px}.wr-mini-grid{grid-template-columns:repeat(3,1fr)}.wr-detail-grid{grid-template-columns:repeat(2,1fr)}}
@media(max-width:991px){.wr-heading h1{font-size:22px}.wr-chart-grid{grid-template-columns:1fr 1fr}.wr-chart-wide{grid-column:1/-1}.wr-hero{grid-template-columns:1fr}.wr-hero-title{margin-bottom:15px}.wr-mini-grid{grid-template-columns:repeat(2,1fr)}}
@media(max-width:767px){.wr-header{display:block}.wr-heading{align-items:flex-start}.wr-logo{width:46px;height:46px}.wr-heading p{font-size:11px}.wr-actions{margin-top:12px}.wr-period{flex:1;min-width:0;font-size:10px}.wr-hero{padding:16px}.wr-hero-kpis{grid-template-columns:repeat(2,1fr)}.wr-hero-kpis article{padding:8px;border-bottom:1px solid #d5eadf}.wr-mini-grid,.wr-chart-grid,.wr-detail-grid{grid-template-columns:1fr}.wr-chart-wide{grid-column:auto}.wr-card{padding:12px}.wr-donut-row{justify-content:center}.wr-table-wrap table{min-width:360px}}
</style>
@endonce
